using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ParalyzingAuraEffect", menuName = "Data/Battle/Effects/Enemy/ParalyzingAura Effect")]
public class ParalyzingAuraEffect : AuraEffects
{
	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		if (amount == EffectsValues.NO_VALUE)
		{
			amount = 1;
		}
		return base.GetEffectDescription(amount, effectOwner);
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		ReferenceSingleton<PlayerDiceHandHolder>.Instance.UpdateDrawDicesAmount(0);
	}
}
